// FUNCTION: BFME2 0x001DB7C9 size=100 name=?sizeWindowsDefault@ControlBarResizer@@QAEXXZ evidence=N:ledger
void ControlBarResizer::sizeWindowsDefault()
{
    ResizerWindowList::iterator it=m_resizerWindowsList.begin();
    GameWindow *win=0;
    while(it!=m_resizerWindowsList.end()) {
        ResizerWindow *record=*it;
        if(!record) { ++it; continue; }
        win=TheWindowManager->winGetWindowFromId(0,TheNameKeyGenerator->nameToKey(record->m_name));
        if(!win) { ++it; continue; }
        win->winSetPosition(record->m_defaultPos.x,record->m_defaultPos.y);
        win->winSetSize(record->m_defaultSize.x,record->m_defaultSize.y);
        ++it;
    }
}

// FUNCTION: BFME2 0x001DB82D size=253 name=?sizeWindowsAlt@ControlBarResizer@@QAEXXZ evidence=N:ledger
void ControlBarResizer::sizeWindowsAlt()
{
    ResizerWindowList::iterator it=m_resizerWindowsList.begin();
    GameWindow *win=0;
    float x=(float)TheDisplay->getWidth()/800;
    float y=(float)TheDisplay->getHeight()/600;
    while(it!=m_resizerWindowsList.end()) {
        ResizerWindow *record=*it;
        if(!record) { ++it; continue; }
        win=TheWindowManager->winGetWindowFromId(0,TheNameKeyGenerator->nameToKey(record->m_name));
        if(!win) { ++it; continue; }
        win->winSetPosition(record->m_altPos.x*x,record->m_altPos.y*y);
        if(record->m_altSize.x>0 || record->m_altSize.y>0)
            win->winSetSize(record->m_altSize.x*x,record->m_altSize.y*y);
        ++it;
    }
}

