ControlBarResizer::~ControlBarResizer()
{
	ResizerWindowList::iterator it = m_resizerWindowsList.begin();
	while (it != m_resizerWindowsList.end()) {
		ResizerWindow *record = *it;
		if (!record) {
			it = m_resizerWindowsList.erase(it);
			continue;
		}
		delete record;
		it = m_resizerWindowsList.erase(it);
	}
	m_resizerWindowsList.clear();
}

// FUNCTION: BFME2 0x001DB9A2 size=199 name=?newResizerWindow@ControlBarResizer@@QAEPAVResizerWindow@@VAsciiString@@@Z evidence=N:ledger

ResizerWindow *ControlBarResizer::newResizerWindow(AsciiString name)
{
	ResizerWindow *record = new ResizerWindow;
	if (!record)
		return 0;
	record->m_name.set(name);
	GameWindow *win = TheWindowManager->winGetWindowFromId(0, TheNameKeyGenerator->nameToKey(name));
	if (!win) {
		delete record;
		return 0;
	}
	win->winGetPosition(&record->m_defaultPos.x, &record->m_defaultPos.y);
	win->winGetSize(&record->m_defaultSize.x, &record->m_defaultSize.y);
	m_resizerWindowsList.push_back(record);
	return record;
}


